// Copyright (c) 2026 Roshan. All rights reserved.package com.roshan.persona.commonimport java.io.IOException/** * NOUS — typed error hierarchy. * * Every error in the system is one of these. No more `throw RuntimeException("...")` * — instead, return `Result.Failure(AppError.Network.Timeout(...))`. * * Each error carries: * - [code] — stable, machine-readable code (used for analytics + retry decisions) * - [message] — developer-facing English message (logged) * - [userMessage] — user-facing localized message key (resolved by UI) * - [cause] — optional root cause throwable * - [retryable] — can the operation be retried? * - [metadata] — additional context (e.g., HTTP status, model name, file path) */sealed class AppError(    val code: String,    val message: String,    val userMessage: String,    open val cause: Throwable? = null,    val retryable: Boolean = false,    val metadata: Map<String, String> = emptyMap(),) {    // ─── Network ──────────────────────────────────────────────────────────    sealed class Network(        code: String,        message: String,        userMessage: String = "user_error_network_generic",        cause: Throwable? = null,        retryable: Boolean = true,        metadata: Map<String, String> = emptyMap(),    ) : AppError(code, message, userMessage, cause, retryable, metadata) {        class Timeout(            durationMs: Long,            cause: Throwable? = null,        ) : Network(            code = "NETWORK_TIMEOUT",            message = "Network call timed out after ${durationMs}ms",            userMessage = "user_error_network_timeout",            cause = cause,            retryable = true,            metadata = mapOf("durationMs" to durationMs.toString()),        )        class NoConnection(cause: Throwable? = null) : Network(            code = "NETWORK_NO_CONNECTION",            message = "Device is offline",            userMessage = "user_error_network_offline",            cause = cause,            retryable = true,        )        class HttpStatus(            val status: Int,            body: String,            cause: Throwable? = null,        ) : Network(            code = "NETWORK_HTTP_$status",            message = "HTTP $status: $body",            userMessage = when (status) {                in 400..499 -> "user_error_network_client"                in 500..599 -> "user_error_network_server"                else -> "user_error_network_generic"            },            cause = cause,            retryable = status in 500..599,            metadata = mapOf("status" to status.toString()),        )        class SslHandshake(cause: Throwable? = null) : Network(            code = "NETWORK_SSL_HANDSHAKE",            message = "SSL handshake failed",            userMessage = "user_error_network_ssl",            cause = cause,            retryable = false,        )    }    // ─── Storage ──────────────────────────────────────────────────────────    sealed class Storage(        code: String,        message: String,        userMessage: String = "user_error_storage_generic",        cause: Throwable? = null,        retryable: Boolean = false,        metadata: Map<String, String> = emptyMap(),    ) : AppError(code, message, userMessage, cause, retryable, metadata) {        class DiskFull(cause: Throwable? = null) : Storage(            code = "STORAGE_DISK_FULL",            message = "Device storage is full",            userMessage = "user_error_storage_disk_full",            cause = cause,            retryable = false,        )        class Corruption(            val path: String,            cause: Throwable? = null,        ) : Storage(            code = "STORAGE_CORRUPTION",            message = "Storage corrupted at $path",            userMessage = "user_error_storage_corruption",            cause = cause,            retryable = false,            metadata = mapOf("path" to path),        )        class MigrationFailed(            val fromVersion: Int,            val toVersion: Int,            cause: Throwable? = null,        ) : Storage(            code = "STORAGE_MIGRATION_FAILED",            message = "DB migration $fromVersion → $toVersion failed",            userMessage = "user_error_storage_migration",            cause = cause,            retryable = false,            metadata = mapOf("from" to fromVersion.toString(), "to" to toVersion.toString()),        )    }    // ─── Permission ───────────────────────────────────────────────────────    sealed class Permission(        code: String,        message: String,        userMessage: String = "user_error_permission_generic",        cause: Throwable? = null,        retryable: Boolean = false,        metadata: Map<String, String> = emptyMap(),    ) : AppError(code, message, userMessage, cause, retryable, metadata) {        class Denied(            val permission: String,        ) : Permission(            code = "PERMISSION_DENIED",            message = "Permission denied: $permission",            userMessage = "user_error_permission_denied",            retryable = true,            metadata = mapOf("permission" to permission),        )        class PermanentlyDenied(            val permission: String,        ) : Permission(            code = "PERMISSION_PERMANENTLY_DENIED",            message = "Permission permanently denied: $permission (must open Settings)",            userMessage = "user_error_permission_permanently_denied",            retryable = false,            metadata = mapOf("permission" to permission),        )        class SpecialAccessRequired(            val settingsIntent: String,        ) : Permission(            code = "PERMISSION_SPECIAL_ACCESS",            message = "Special permission required (Settings: $settingsIntent)",            userMessage = "user_error_permission_special",            retryable = false,            metadata = mapOf("settingsIntent" to settingsIntent),        )    }    // ─── LLM ──────────────────────────────────────────────────────────────    sealed class Llm(        code: String,        message: String,        userMessage: String = "user_error_llm_generic",        cause: Throwable? = null,        retryable: Boolean = false,        metadata: Map<String, String> = emptyMap(),    ) : AppError(code, message, userMessage, cause, retryable, metadata) {        class ModelMissing(            val modelId: String,        ) : Llm(            code = "LLM_MODEL_MISSING",            message = "Model $modelId is not downloaded",            userMessage = "user_error_llm_model_missing",            retryable = false,            metadata = mapOf("modelId" to modelId),        )        class ModelLoadFailed(            val modelId: String,            cause: Throwable? = null,        ) : Llm(            code = "LLM_MODEL_LOAD_FAILED",            message = "Failed to load model $modelId",            userMessage = "user_error_llm_load_failed",            cause = cause,            retryable = true,            metadata = mapOf("modelId" to modelId),        )        class OutOfMemory(            val modelId: String,            val requiredMb: Int,        ) : Llm(            code = "LLM_OUT_OF_MEMORY",            message = "Not enough memory to run $modelId (needs ${requiredMb}MB)",            userMessage = "user_error_llm_oom",            retryable = false,            metadata = mapOf("modelId" to modelId, "requiredMb" to requiredMb.toString()),        )        class ContextOverflow(            val contextLength: Int,            val inputTokens: Int,        ) : Llm(            code = "LLM_CONTEXT_OVERFLOW",            message = "Input $inputTokens tokens > context $contextLength",            userMessage = "user_error_llm_context_overflow",            retryable = false,            metadata = mapOf(                "contextLength" to contextLength.toString(),                "inputTokens" to inputTokens.toString(),            ),        )        class RateLimited(            val provider: String,            val retryAfterMs: Long,        ) : Llm(            code = "LLM_RATE_LIMITED",            message = "Provider $provider rate limited, retry after ${retryAfterMs}ms",            userMessage = "user_error_llm_rate_limited",            retryable = true,            metadata = mapOf(                "provider" to provider,                "retryAfterMs" to retryAfterMs.toString(),            ),        )    }    // ─── Skill ────────────────────────────────────────────────────────────    sealed class Skill(        code: String,        message: String,        userMessage: String = "user_error_skill_generic",        cause: Throwable? = null,        retryable: Boolean = false,        metadata: Map<String, String> = emptyMap(),    ) : AppError(code, message, userMessage, cause, retryable, metadata) {        class NotFound(            val skillName: String,        ) : Skill(            code = "SKILL_NOT_FOUND",            message = "Skill '$skillName' not registered",            userMessage = "user_error_skill_not_found",            retryable = false,            metadata = mapOf("skillName" to skillName),        )        class Crashed(            val skillName: String,            cause: Throwable? = null,        ) : Skill(            code = "SKILL_CRASHED",            message = "Skill '$skillName' threw an exception",            userMessage = "user_error_skill_crashed",            cause = cause,            retryable = true,            metadata = mapOf("skillName" to skillName),        )        class TimedOut(            val skillName: String,            val durationMs: Long,        ) : Skill(            code = "SKILL_TIMED_OUT",            message = "Skill '$skillName' exceeded ${durationMs}ms budget",            userMessage = "user_error_skill_timeout",            retryable = true,            metadata = mapOf("skillName" to skillName, "durationMs" to durationMs.toString()),        )    }    // ─── Security ─────────────────────────────────────────────────────────    sealed class Security(        code: String,        message: String,        userMessage: String = "user_error_security_generic",        cause: Throwable? = null,        retryable: Boolean = false,        metadata: Map<String, String> = emptyMap(),    ) : AppError(code, message, userMessage, cause, retryable, metadata) {        class AuthenticationFailed(            val what: String,        ) : Security(            code = "SECURITY_AUTH_FAILED",            message = "Authentication failed for $what",            userMessage = "user_error_security_auth",            retryable = false,            metadata = mapOf("what" to what),        )        class IntegrityCheckFailed(            val reason: String,        ) : Security(            code = "SECURITY_INTEGRITY",            message = "Device integrity check failed: $reason",            userMessage = "user_error_security_integrity",            retryable = false,            metadata = mapOf("reason" to reason),        )        class JailbreakDetected(            val signals: List<String>,        ) : Security(            code = "SECURITY_JAILBREAK",            message = "Device appears rooted/jailbroken. Signals: $signals",            userMessage = "user_error_security_jailbreak",            retryable = false,            metadata = mapOf("signals" to signals.joinToString(",")),        )    }    // ─── Configuration ────────────────────────────────────────────────────    sealed class Configuration(        code: String,        message: String,        userMessage: String = "user_error_config_generic",        cause: Throwable? = null,        retryable: Boolean = false,        metadata: Map<String, String> = emptyMap(),    ) : AppError(code, message, userMessage, cause, retryable, metadata) {        class MissingApiKey(            val provider: String,        ) : Configuration(            code = "CONFIG_MISSING_API_KEY",            message = "API key for $provider not configured",            userMessage = "user_error_config_api_key",            retryable = false,            metadata = mapOf("provider" to provider),        )        class InvalidRemoteConfig(            val key: String,            cause: Throwable? = null,        ) : Configuration(            code = "CONFIG_REMOTE_INVALID",            message = "Remote config '$key' has invalid value",            userMessage = "user_error_config_remote",            cause = cause,            retryable = true,            metadata = mapOf("key" to key),        )        class ProviderNotFound(            val providerId: String,        ) : Configuration(            code = "CONFIG_PROVIDER_NOT_FOUND",            message = "Cloud provider '$providerId' not found in registry",            userMessage = "user_error_config_provider_not_found",            retryable = false,            metadata = mapOf("providerId" to providerId),        )        class ProviderAlreadyExists(            val providerId: String,        ) : Configuration(            code = "CONFIG_PROVIDER_EXISTS",            message = "Cloud provider '$providerId' already exists",            userMessage = "user_error_config_provider_exists",            retryable = false,            metadata = mapOf("providerId" to providerId),        )        class ProviderBuiltinCannotDelete(            val providerId: String,        ) : Configuration(            code = "CONFIG_PROVIDER_BUILTIN",            message = "Cannot delete built-in provider '$providerId' — disable it instead",            userMessage = "user_error_config_provider_builtin",            retryable = false,            metadata = mapOf("providerId" to providerId),        )        class InvalidProviderConfig(            val reason: String,        ) : Configuration(            code = "CONFIG_PROVIDER_INVALID",            message = "Invalid provider config: $reason",            userMessage = "user_error_config_provider_invalid",            retryable = false,            metadata = mapOf("reason" to reason),        )        class BudgetExceeded(            val monthlyBudgetUsd: Float,            val monthlySpentUsd: Float,        ) : Configuration(            code = "CONFIG_BUDGET_EXCEEDED",            message = "Monthly LLM budget exceeded: spent \$$monthlySpentUsd of \$$monthlyBudgetUsd",            userMessage = "user_error_config_budget_exceeded",            retryable = false,            metadata = mapOf(                "monthlyBudgetUsd" to monthlyBudgetUsd.toString(),                "monthlySpentUsd" to monthlySpentUsd.toString(),            ),        )    }    // ─── Hardware (Module 10 v2 — Review 2 Fix C) ─────────────────────────    /**     * Hardware-related errors for system operations.     *     * Every Android hardware API call (CameraManager, AudioManager, etc.)     * can throw — these are mapped to typed errors so the Brain can show     * user-friendly messages instead of crashing.     */    sealed class Hardware(        code: String,        message: String,        userMessage: String = "user_error_hardware_generic",        cause: Throwable? = null,        retryable: Boolean = false,        metadata: Map<String, String> = emptyMap(),    ) : AppError(code, message, userMessage, cause, retryable, metadata) {        /** Hardware is in use by another app (e.g., camera blocked by Instagram). */        class InUse(            val resource: String,            cause: Throwable? = null,        ) : Hardware(            code = "HARDWARE_IN_USE",            message = "$resource is in use by another app",            userMessage = "user_error_hardware_in_use",            cause = cause,            retryable = true,            metadata = mapOf("resource" to resource),        )        /** Hardware not available on this device (e.g., torch on a phone without flash). */        class Unavailable(            val resource: String,            cause: Throwable? = null,        ) : Hardware(            code = "HARDWARE_UNAVAILABLE",            message = "$resource is not available on this device",            userMessage = "user_error_hardware_unavailable",            cause = cause,            retryable = false,            metadata = mapOf("resource" to resource),        )        /** Operation refused due to thermal throttling (Review 2 Elite 2). */        class ThermalThrottled(            val headroom: Float,            cause: Throwable? = null,            /** User-facing advice string (displayed by UI as a SnackBar / toast). */            val userAdvice: String = "Device is hot — please let it cool down before retrying.",        ) : Hardware(            code = "HARDWARE_THERMAL_THROTTLED",            message = "Operation refused — device is thermally throttled " +                "(headroom=$headroom). $userAdvice",            userMessage = "user_error_hardware_thermal",            cause = cause,            retryable = true,            metadata = mapOf(                "headroom" to headroom.toString(),                "userAdvice" to userAdvice,            ),        )        /** Operation not supported by the carrier / OEM (e.g., tethering blocked). */        class Unsupported(            val resource: String,            cause: Throwable? = null,        ) : Hardware(            code = "HARDWARE_UNSUPPORTED",            message = "$resource is not supported on this device/carrier",            userMessage = "user_error_hardware_unsupported",            cause = cause,            retryable = false,            metadata = mapOf("resource" to resource),        )        /** Catch-all for unmapped hardware exceptions. */        class Unknown(            val resource: String,            cause: Throwable? = null,        ) : Hardware(            code = "HARDWARE_UNKNOWN",            message = "Unknown hardware error on $resource",            userMessage = "user_error_hardware_generic",            cause = cause,            retryable = false,            metadata = mapOf("resource" to resource),        )    }    // ─── Unknown (catch-all) ──────────────────────────────────────────────    class Unknown(        cause: Throwable? = null,        correlationId: CorrelationId = CorrelationId.generate(),    ) : AppError(        code = "UNKNOWN",        message = "Unexpected error (correlationId=${correlationId.value})",        userMessage = "user_error_unknown",        cause = cause,        retryable = false,        metadata = mapOf("correlationId" to correlationId.value),    )    companion object {        /**         * Convert any throwable to an [AppError], preserving type info where possible.         */        fun from(            throwable: Throwable,            correlationId: CorrelationId = CorrelationId.generate(),        ): AppError = when (throwable) {            is java.net.SocketTimeoutException -> Network.Timeout(                durationMs = 30_000, // best-effort guess                cause = throwable,            )            is java.net.UnknownHostException -> Network.NoConnection(cause = throwable)            is IOException -> Network.NoConnection(cause = throwable)            is SecurityException -> Permission.Denied(                permission = throwable.message ?: "unknown",            )            else -> Unknown(cause = throwable, correlationId = correlationId)        }    }}